import React, { useEffect, useState } from "react";

export default function Products() {

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  const [selectedId, setSelectedId] = useState(null);
  const [stockQty, setStockQty] = useState(0);

  /* =========================
     FETCH PRODUCTS
  ========================= */
  const fetchProducts = () => {

    fetch("http://localhost/Capstone--Development/customer/api_products.php?action=list")
      .then(res => res.json())
      .then(data => {

        if (Array.isArray(data)) {
          setProducts(data);
        } else {
          setProducts([]);
        }

      })
      .catch(() => setProducts([]))
      .finally(() => setLoading(false));

  };

  useEffect(() => {
    fetchProducts();
  }, []);

  /* =========================
     UPDATE STOCK
  ========================= */
  const updateStock = (id, type) => {

    fetch("http://localhost/Capstone--Development/staff/api_update_stock.php", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id,
        qty: stockQty,
        type // "in" or "out"
      })
    })
      .then(res => res.json())
      .then(data => {

        if (data.status === "success") {
          fetchProducts();
          setSelectedId(null);
          setStockQty(0);
        } else {
          console.error(data.message);
        }

      })
      .catch(err => console.error(err));

  };

  if (loading) {
    return <p className="p-10 text-gray-400">Loading products...</p>;
  }

  return (

    <div className="p-8 bg-[#fafafa] min-h-screen">

      <h1 className="text-3xl font-bold mb-6">
        Products Inventory
      </h1>

      <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6">

        {products.map(product => (

          <div key={product.id} className="bg-white p-5 rounded-xl shadow">

            <img
              src={`http://localhost/Capstone--Development/uploads/${product.image}`}
              className="h-40 w-full object-cover rounded-lg mb-3"
              alt={product.name}
            />

            <h2 className="font-bold text-lg">
              {product.name}
            </h2>

            <p className="text-sm text-gray-500 mb-2">
              Category: {product.category}
            </p>

            {/* STOCK DISPLAY */}
            <p className="text-sm mb-3">
              Stock: <span className="font-bold">{product.stock || 0}</span>
            </p>

            {/* STOCK INPUT */}
            {selectedId === product.id ? (

              <div className="flex gap-2">

                <input
                  type="number"
                  value={stockQty}
                  onChange={(e) => setStockQty(Number(e.target.value))}
                  className="border p-1 w-20"
                  placeholder="Qty"
                />

                <button
                  onClick={() => updateStock(product.id, "in")}
                  className="bg-green-500 text-white px-2 py-1 text-xs"
                >
                  Stock In
                </button>

                <button
                  onClick={() => updateStock(product.id, "out")}
                  className="bg-red-500 text-white px-2 py-1 text-xs"
                >
                  Stock Out
                </button>

              </div>

            ) : (

              <button
                onClick={() => setSelectedId(product.id)}
                className="mt-2 bg-black text-white px-3 py-1 text-xs rounded"
              >
                Update Stock
              </button>

            )}

          </div>

        ))}

      </div>

    </div>

  );

}
